RLPolicyEvaluationSchema::StatusEnum RLPolicyEvaluationSchema::toStatusEnum(const utility::string_t& value) const
{
    
    if (value == utility::conversions::to_string_t("pending")) {
        return StatusEnum::PENDING;
    }
    
    if (value == utility::conversions::to_string_t("running")) {
        return StatusEnum::RUNNING;
    }
    
    if (value == utility::conversions::to_string_t("completed")) {
        return StatusEnum::COMPLETED;
    }
    
    if (value == utility::conversions::to_string_t("failed")) {
        return StatusEnum::FAILED;
    }
    
    if (value == utility::conversions::to_string_t("cancelled")) {
        return StatusEnum::CANCELLED;
    }
    
    throw std::invalid_argument("Invalid value for conversion to StatusEnum");
}


const utility::string_t RLPolicyEvaluationSchema::fromStatusEnum(const StatusEnum value) const
{
    switch(value)
    {
        
        case StatusEnum::PENDING: return utility::conversions::to_string_t("pending");
        
        case StatusEnum::RUNNING: return utility::conversions::to_string_t("running");
        
        case StatusEnum::COMPLETED: return utility::conversions::to_string_t("completed");
        
        case StatusEnum::FAILED: return utility::conversions::to_string_t("failed");
        
        case StatusEnum::CANCELLED: return utility::conversions::to_string_t("cancelled");
        
    }
}


